/* Includes */
#include <errno.h>
#include <stdint.h>
#include <stddef.h>

/**
 * Pointer to the current high watermark of the heap usage
 */
static uint8_t *__sbrk_heap_end = NULL;

/**
 * @brief _sbrk() allocates memory to the newlib heap and is used by malloc
 *        and others from the C library
 *
 * @verbatim
 * ############################################################################
 * #  .data  #  .bss  # bounded newlib heap # mailbox/OTA #    MSP stack      #
 * ############################################################################
 * ^-- RAM start      ^-- __heap_start       __heap_limit  _estack, RAM end --^
 * @endverbatim
 *
 * This product keeps the Boot/App fault mailbox fixed at 0x2000BC40.  The
 * linker exposes the otherwise empty range before it as a dedicated heap so
 * malloc can use that RAM without ever reaching the mailbox or OTA workspace.
 *
 * @param incr Memory size
 * @return Pointer to allocated memory
 */
void *_sbrk(ptrdiff_t incr)
{
  extern uint8_t __heap_start; /* Symbols defined in the linker script */
  extern uint8_t __heap_limit;
  const uint8_t *min_heap = &__heap_start;
  const uint8_t *max_heap = &__heap_limit;
  uint8_t *prev_heap_end;

  /* Initialize heap end at first call */
  if (NULL == __sbrk_heap_end)
  {
    __sbrk_heap_end = &__heap_start;
  }

  /* Protect both ends of the dedicated heap region. */
  if (((incr > 0) && ((size_t)incr > (size_t)(max_heap - __sbrk_heap_end))) ||
      ((incr < 0) && ((size_t)(-incr) > (size_t)(__sbrk_heap_end - min_heap))))
  {
    errno = ENOMEM;
    return (void *)-1;
  }

  prev_heap_end = __sbrk_heap_end;
  __sbrk_heap_end += incr;

  return (void *)prev_heap_end;
}

#if defined(__PICOLIBC__)
  // Picolibc expects syscalls without the leading underscore.
  // This creates a strong alias so that
  // calls to `sbrk()` are resolved to our `_sbrk()` implementation.
  __strong_reference(_sbrk, sbrk);
#endif
